using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
namespace RcsMap {
 public static class ShapeGeometryTests {
  static int count;
  static void Check(bool value,string name){if(!value)throw new Exception("shape geometry: "+name);count++;}
  static void Near(double actual,double expected,string name){Check(Math.Abs(actual-expected)<1e-6,name+" ("+actual+", "+expected+")");}
  static void Throws(Action action,string name){bool caught=false;try{action();}catch{caught=true;}Check(caught,name);}
  static TerrainSurface Rect(double x=1000,double y=1000,double w=2000,double h=1200){return new TerrainSurface{X=x,Y=y,Width=w,Depth=h,SpeedLimit=200};}
  static void RotateAround(TerrainSurface s,double degrees,double cx,double cy){double a=degrees*Math.PI/180,ca=Math.Cos(a),sa=Math.Sin(a),axis=SurfaceOutline.AxisDegrees(s);var p=SurfaceOutline.Points(s).Select(v=>new TerrainVertex(cx+(v.X-cx)*ca-(v.Y-cy)*sa,cy+(v.X-cx)*sa+(v.Y-cy)*ca)).ToList();SurfaceOutline.SetWorld(s,p);if(s.Kind!=SurfaceKind.水平平台){s.Kind=SurfaceKind.任意方向直坡道;s.RampDirectionDeg=axis+degrees;}}
  public static void Run(string folder){Directory.CreateDirectory(folder);count=0;
   var s=Rect();Check(s.Outline==null,"legacy outline absent");Check(s.Contains(1000,1000)&&s.Contains(3000,2200),"legacy boundaries");Check(!s.Contains(999,1000),"outside legacy rectangle");s.Kind=SurfaceKind.沿X直坡道;s.Z1=400;Near(s.HeightAt(1250,1700),50,"legacy X exact height");Near(SurfaceOutline.Gradient(s)[0],.2,"legacy X gradient");s.Kind=SurfaceKind.沿Y直坡道;Near(s.HeightAt(1200,1300),100,"legacy Y exact height");
   s=Rect();SurfaceOutline.ApplyPreset(s,"triangle");Check(s.Outline.Count==3,"triangle vertex count");Check(s.Contains(2000,1600),"triangle interior");Check(!s.Contains(2900,2100),"AABB corner excluded");Check(!s.Contains(1100,1050,100),"triangle eroded margin");double lo,hi;Check(SurfaceOutline.Interval(SurfaceOutline.Points(s),0,2100,4000,2100,out lo,out hi),"triangle segment clips");Check(hi<.8&&lo>.2,"triangle interval differs from bounding rectangle");
   var before=SurfaceOutline.Points(s).Select(p=>p.X+":"+p.Y).ToArray();Throws(()=>SurfaceOutline.SetWorld(s,new[]{new TerrainVertex(0,0),new TerrainVertex(1000,0),new TerrainVertex(300,300),new TerrainVertex(1000,1000),new TerrainVertex(0,1000)}),"concave edit rejected");Check(SurfaceOutline.Points(s).Select(p=>p.X+":"+p.Y).SequenceEqual(before),"failed edit atomic");Throws(()=>SurfaceOutline.SetWorld(s,new[]{new TerrainVertex(0,0),new TerrainVertex(1000,1000),new TerrainVertex(0,1000),new TerrainVertex(1000,0)}),"self intersection rejected");Throws(()=>SurfaceOutline.SetWorld(s,new[]{new TerrainVertex(0,0),new TerrainVertex(1000,0),new TerrainVertex(1000,0),new TerrainVertex(0,1000)}),"zero edge rejected");Throws(()=>SurfaceOutline.SetWorld(s,new[]{new TerrainVertex(0,0),new TerrainVertex(500,0),new TerrainVertex(1000,0)}),"zero area rejected");Throws(()=>SurfaceOutline.SetWorld(s,new[]{new TerrainVertex(Double.NaN,0),new TerrainVertex(1000,0),new TerrainVertex(0,1000)}),"nonfinite vertex rejected");
   s=Rect();var points=SurfaceOutline.Points(s);points.Insert(1,new TerrainVertex(2000,1000));SurfaceOutline.SetWorld(s,points);Check(s.Outline.Count==5&&SurfaceOutline.IsConvex(SurfaceOutline.Points(s)),"collinear edge control retained");SurfaceOutline.SetWorld(s,SurfaceOutline.Points(s).AsEnumerable().Reverse());Check(SurfaceOutline.Area(SurfaceOutline.Points(s))>0,"clockwise user edit normalized");
   SurfaceOutline.ApplyPreset(s,"ellipse");Check(s.Outline.Count==16,"ellipse is explicit16-gon");Check(s.Contains(2000,1600,400),"ellipse interior margin");Check(!s.Contains(1050,1050),"ellipse corner empty");SurfaceOutline.ApplyPreset(s,"hexagon");Check(s.Outline.Count==6,"hexagon preset");Near(s.Width,2000,"hexagon preserves bounding width");Near(s.Depth,1200,"hexagon preserves bounding depth");
   s=Rect();s.Kind=SurfaceKind.沿X直坡道;s.Z1=300;SurfaceOutline.ApplyPreset(s,"trapezoid");Check(SurfaceOutline.MeetsGround(s),"trapezoid has actual low cap edge");Check(s.Contains(s.X+s.Width-10,s.Y+s.Depth/2),"trapezoid high cap interior");var heights=SurfaceOutline.Points(s).Select(v=>s.HeightAt(v.X,v.Y)).ToArray();SurfaceOutline.Rotate(s,37);Check(s.Kind==SurfaceKind.任意方向直坡道,"rotation creates arbitrary ramp");Near(SurfaceOutline.AxisDegrees(s),37,"ramp axis rotates");for(int i=0;i<heights.Length;i++)Near(s.HeightAt(SurfaceOutline.Points(s)[i].X,SurfaceOutline.Points(s)[i].Y),heights[i],"rotation preserves vertex height "+i);Check(SurfaceOutline.MeetsGround(s),"rotated low cap remains connected to ground");var g=SurfaceOutline.Gradient(s);Near(Math.Atan2(g[1],g[0])*180/Math.PI,37,"gradient direction");
   var a=Rect();a.Kind=SurfaceKind.沿X直坡道;a.Z1=300;var b=Rect(3000,1000,2000,1200);b.Z0=300;Check(TerrainGeometry.SurfacesMeet(a,b),"legacy shared cap");RotateAround(a,29,2000,1600);RotateAround(b,29,2000,1600);Check(TerrainGeometry.SurfacesMeet(a,b),"rotated equal cap connection");b.Z0=301;Check(!TerrainGeometry.SurfacesMeet(a,b),"rotated height gap rejected");b.Z0=300;b.X+=20;Check(!TerrainGeometry.SurfacesMeet(a,b),"rotated physical gap rejected");
   var overlap=Rect();var overlap2=Rect(1500,1200);Check(!TerrainGeometry.SurfacesMeet(overlap,overlap2),"XY area overlap not connection");var corner=Rect(3000,2200);Check(!TerrainGeometry.SurfacesMeet(overlap,corner),"corner touch not connection");var tip=Rect();tip.Kind=SurfaceKind.沿X直坡道;tip.Z1=300;SurfaceOutline.SetWorld(tip,new[]{new TerrainVertex(1000,1600),new TerrainVertex(3000,1000),new TerrainVertex(3000,2200)});Check(!SurfaceOutline.MeetsGround(tip),"zero height corner not ground cap");
   var target=SurfaceOutline.Points(Rect(0,0,1000,1000));var left=SurfaceOutline.Points(Rect(0,0,500,1000));var right=SurfaceOutline.Points(Rect(500,0,500,1000));Check(SurfaceOutline.CoveredByUnion(target,new List<List<TerrainVertex>>{left,right}),"area union covers seamless halves");right=SurfaceOutline.Points(Rect(501,0,499,1000));Check(!SurfaceOutline.CoveredByUnion(target,new List<List<TerrainVertex>>{left,right}),"area union catches internal gap");var diamond=Rect(0,0,1000,1000);SurfaceOutline.SetWorld(diamond,new[]{new TerrainVertex(500,0),new TerrainVertex(1000,500),new TerrainVertex(500,1000),new TerrainVertex(0,500)});Check(!SurfaceOutline.CoveredByUnion(target,new List<List<TerrainVertex>>{SurfaceOutline.Points(diamond)}),"bbox coverage cannot replace polygon coverage");
   var tri=Rect(0,0,1000,1000);SurfaceOutline.SetWorld(tri,new[]{new TerrainVertex(0,0),new TerrainVertex(1000,0),new TerrainVertex(0,1000)});Check(!SurfaceOutline.Interval(SurfaceOutline.Expanded(tri,100),800,800,900,900,out lo,out hi),"expanded polygon avoids AABB overhead false hit");Check(SurfaceOutline.Interval(SurfaceOutline.Expanded(tri,100),500,500,700,500,out lo,out hi),"expanded polygon includes body envelope near edge");
   var outer=new List<TerrainVertex>{new TerrainVertex(0,0),new TerrainVertex(1000,0),new TerrainVertex(500,866)};var ring=new List<List<TerrainVertex>>{new List<TerrainVertex>{new TerrainVertex(0,0),new TerrainVertex(1000,0),new TerrainVertex(750,144),new TerrainVertex(250,144)},new List<TerrainVertex>{new TerrainVertex(1000,0),new TerrainVertex(500,866),new TerrainVertex(500,577),new TerrainVertex(750,144)},new List<TerrainVertex>{new TerrainVertex(500,866),new TerrainVertex(0,0),new TerrainVertex(250,144),new TerrainVertex(500,577)}};Check(!SurfaceOutline.CoveredByUnion(outer,ring),"three convex covers cannot conceal an interior hole");
   var d=ContinuousTests.Demo();d.Version=6;foreach(var surface in d.Terrain.Surfaces)SurfaceOutline.ApplyPreset(surface,"rectangle");Check(TerrainGeometry.Validate(d).Count==0,"explicit polygon rectangles preserve valid continuous route");string json=d.Json();Check(d.Clone().Json()==json,"v6 outline roundtrip");Check(d.Points.Count==2,"shape geometry does not add task points");var tilted=d.Terrain.Surfaces[1];var original=SurfaceOutline.Points(tilted);tilted.X+=123;tilted.Y-=50;var moved=SurfaceOutline.Points(tilted);for(int i=0;i<original.Count;i++){Near(moved[i].X-original[i].X,123,"normalized translation X");Near(moved[i].Y-original[i].Y,-50,"normalized translation Y");}
   d=ContinuousTests.Demo();d.Version=6;var deck=d.Terrain.Surfaces[1];double ox=deck.X,oy=deck.Y,w=deck.Width,h=deck.Depth;SurfaceOutline.SetWorld(deck,new[]{new TerrainVertex(ox+w/2,oy),new TerrainVertex(ox+w,oy+h/2),new TerrainVertex(ox+w/2,oy+h),new TerrainVertex(ox,oy+h/2)});var obstacle=new Obstacle(ox+.45*w,oy+.05*h,.5*w,.5*h){SurfaceId=deck.Id};Check(deck.Contains(obstacle.X,obstacle.Y)&&deck.Contains(obstacle.X+obstacle.Width,obstacle.Y+obstacle.Height)&&!deck.Contains(obstacle.X+obstacle.Width,obstacle.Y),"opposite corners alone are insufficient");d.Obstacles.Add(obstacle);Check(TerrainGeometry.Validate(d).Any(e=>e.Contains("障碍物超出")),"all obstacle corners validated against actual polygon");
   d=ContinuousTests.Demo();d.Version=6;foreach(var surface in d.Terrain.Surfaces)SurfaceOutline.ApplyPreset(surface,surface.Kind==SurfaceKind.水平平台?"rectangle":"trapezoid");TerrainLeg originalLeg;string error;Check(TerrainGeometry.TryLeg(d,d.Points[0],d.Points[1],out originalLeg,out error),"trapezoid continuous chain");Check(TerrainGeometry.Validate(d).Count==0,"trapezoid ramp body envelope");double originalLength=originalLeg.Length;foreach(var surface in d.Terrain.Surfaces)RotateAround(surface,10,5000,2500);double rot=10*Math.PI/180;foreach(var point in d.Points){double x=point.X-5000,y=point.Y-2500;point.X=5000+x*Math.Cos(rot)-y*Math.Sin(rot);point.Y=2500+x*Math.Sin(rot)+y*Math.Cos(rot);}TerrainLeg rotatedLeg;Check(TerrainGeometry.TryLeg(d,d.Points[0],d.Points[1],out rotatedLeg,out error),"rotated trapezoid chain resolves");Check(rotatedLeg.Spans.Count==5,"rotated chain retains five internal surfaces");Near(rotatedLeg.Length,originalLength,"rigid rotation preserves 3D route length");Check(TerrainGeometry.Validate(d).Count==0,"rotated trapezoid clearance and envelope");
   var under=new MapDocument{Version=6,Terrain=new TerrainMap{BodyHeight=200,ClearanceMargin=20}};under.Settings.Width=10000;under.Settings.Height=5000;under.Settings.Radius=230;under.Settings.PositionTolerance=20;var ceiling=Rect(3000,1800,2000,1400);ceiling.Z0=300;ceiling.Thickness=200;SurfaceOutline.SetWorld(ceiling,new[]{new TerrainVertex(4000,1800),new TerrainVertex(5000,2500),new TerrainVertex(4000,3200),new TerrainVertex(3000,2500)});under.Terrain.Surfaces.Add(ceiling);under.Points.Add(new Waypoint(2700,1900,0,100));under.Points.Add(new Waypoint(3100,1900,0,100));Check(!TerrainGeometry.Validate(under).Any(e=>e.Contains("净空不足")),"empty polygon AABB corner does not create false overhead collision");under.Points[1].X=4300;under.Points[1].Y=2500;Check(TerrainGeometry.Validate(under).Any(e=>e.Contains("净空不足")),"actual polygon overhead still blocks insufficient clearance");
   d=ContinuousTests.Demo();d.Version=6;d.TerrainDrive=new TerrainDriveSettings();DraftRules.Check(d);Check(TerrainGeometry.CanOpenDraft(d),"v6 terrain drive draft remains editable");
   d=ContinuousTests.Demo();foreach(var surface in d.Terrain.Surfaces){surface.Y=2240;surface.Depth=520;}TerrainLeg narrow;Check(TerrainGeometry.TryLeg(d,d.Points[0],d.Points[1],out narrow,out error),"narrow route geometry resolves");Check(TerrainGeometry.LegFits(d,d.Points[0],d.Points[1],narrow,250),"legacy envelope250 fits narrow corridor");Check(!TerrainGeometry.LegFits(d,d.Points[0],d.Points[1],narrow,270),"runtime lateral and arrival budget cannot use legacy smaller envelope");
   File.WriteAllText(Path.Combine(folder,"shape-geometry-selftest.txt"),"PASS "+count+" convex terrain geometry checks\n");Console.WriteLine("PASS "+count+" convex terrain geometry checks");
  }
 }
}
